 const rotatingLists=[...(shopping?[shopping]:[]),...(checklist?[checklist]:[]),...allShopping.filter(e=>e.id!==shopping?.id),...allCheck.filter(e=>e.id!==checklist?.id)];
 const rotated=rotatingLists[rotation%Math.max(rotatingLists.length,1)];
