function Empty({text,action,onClick}:{text:string;action?:string;onClick?:()=>void}){return <div className="empty-state"><House size={30}/><h3>Une place pour l’essentiel.</h3><p>{text}</p>{action&&<button className="primary-button" onClick={onClick}><Plus size={15}/>{action}</button>}</div>;}
function isDescendant(id:string|undefined,parent:string,entities:Entity[]){const seen=new Set<string>();while(id&&!seen.has(id)){if(id===parent)return true;seen.add(id);id=entities.find(e=>e.id===id)?.data.parentId;}return false;}

function AddProduct({modal,snapshot,busy,error,onSave}:{modal:Extract<Modal,{type:"add"}>;snapshot:Snapshot;busy:boolean;error:string;onSave:(c:Command)=>Promise<void>}) {
 const [name,setName]=useState(modal.text),[saveProduct,setSaveProduct]=useState(true),[quantity,setQuantity]=useState(1),[unit,setUnit]=useState(""),[existing,setExisting]=useState("");
 const products=snapshot.entities.filter(e=>e.kind==="product");
 return <><DialogTitle className="dialog-title">{modal.barcode?"Un nouveau code-barres":"Ajouter un produit"}</DialogTitle><DialogDescription>{modal.barcode?"Associez ce code à un produit pour le retrouver lors des prochains scans.":"Choisissez si ce produit doit rester dans votre catalogue."}</DialogDescription>{modal.barcode&&<span className="barcode-label">{modal.barcode}</span>}<form className="form-stack" onSubmit={async e=>{e.preventDefault();try{await onSave({action:"addItem",listId:modal.listId,name:existing?undefined:name.trim(),productId:existing||undefined,saveProduct,barcode:modal.barcode,quantity,unit});}catch{}}}>{modal.barcode&&<label className="field">Associer à un produit existant<Choice label="Produit à associer" value={existing} onChange={setExisting} options={[{value:"",label:"Créer un nouveau produit"},...products.map(p=>({value:p.id,label:String(p.data.name)}))]}/></label>}{!existing&&<label className="field">Nom du produit<input autoFocus required value={name} onChange={e=>setName(e.target.value)} maxLength={150}/></label>}<div className="form-row"><label className="field">Quantité<input required type="number" min="0.01" max="10000" step="0.01" value={quantity} onChange={e=>setQuantity(Number(e.target.value))}/></label><label className="field">Unité (facultatif)<input placeholder="pièces, packs, kg…" value={unit} onChange={e=>setUnit(e.target.value)} maxLength={50}/></label></div>{!modal.barcode&&<label className="check-field"><Checkbox checked={saveProduct} onCheckedChange={v=>setSaveProduct(!!v)}/>Enregistrer ce produit pour le réutiliser</label>}<p className="helper">{modal.barcode?"Le produit et ce code seront enregistrés dans le catalogue du foyer.":saveProduct?"Ce produit sera disponible pour les prochaines listes.":"Ce produit sera ajouté uniquement à cette liste."}</p>{error&&<p role="alert" className="error-text">{error}</p>}<button type="submit" disabled={busy} className="primary-button">{busy?"Ajout…":"Ajouter à la liste"}</button></form></>;
}

function HouseholdForm({user,busy,error,onSave}:{user:User|null;busy:boolean;error:string;onSave:(c:Command)=>Promise<void>}) {
 const [tab,setTab]=useState("create"),[name,setName]=useState(""),[code,setCode]=useState("");
 return <><DialogTitle className="dialog-title">Bienvenue chez vous.</DialogTitle><DialogDescription>Un espace partagé, et un tableau de bord pour chacun.</DialogDescription>{!user?<><p className="helper">Connectez-vous à MyHomeIA pour créer un foyer ou en rejoindre un. L’aperçu contient uniquement des données d’exemple.</p><a className="primary-button" href="/connexion">Se connecter</a><a className="secondary-button mt-3" href="/inscription">Créer un compte</a></>:<><Tabs value={tab} onValueChange={setTab}><TabsList className="w-full"><TabsTrigger value="create" className="flex-1">Créer un foyer</TabsTrigger><TabsTrigger value="join" className="flex-1">Rejoindre un foyer</TabsTrigger></TabsList></Tabs><form className="form-stack" onSubmit={async e=>{e.preventDefault();try{await onSave(tab==="create"?{action:"createHousehold",name:name.trim()}:{action:"joinHousehold",code:code.trim()});}catch{}}}>{tab==="create"?<><label className="field">Nom du foyer<input required autoFocus placeholder="Notre maison" value={name} onChange={e=>setName(e.target.value)} maxLength={150}/></label><p className="helper">Vous serez automatiquement administrateur. Un code permettra aux autres membres de vous rejoindre.</p></>:<label className="field">Code unique du foyer<input required autoFocus placeholder="Code transmis par un administrateur" value={code} onChange={e=>setCode(e.target.value)} maxLength={80}/></label>}{error&&<p className="error-text" role="alert">{error}</p>}<button className="primary-button" disabled={busy} type="submit">{tab==="create"?"Créer mon foyer":"Rejoindre ce foyer"}</button></form></>}</>;
}

function SettingsPanel({snapshot,busy,demo,isAdmin,onSave,onRename,onNotifications}:{snapshot:Snapshot;busy:boolean;demo:boolean;isAdmin:boolean;onSave:(p:Preferences)=>Promise<void>;onRename:(name:string)=>Promise<void>;onNotifications:()=>void}) {
 const [p,setP]=useState<Preferences>({...snapshot.preferences}),[name,setName]=useState(snapshot.household?.name||"");
 const update=(key:keyof Preferences,value:unknown)=>setP(p=>({...p,[key]:value}));
 return <div className="settings-grid"><form className="management-card settings-section form-stack" onSubmit={async e=>{e.preventDefault();try{await onSave(p);toast.success("Votre tableau de bord est configuré");}catch{}}}><h3>Mon tableau de bord</h3><p className="helper">Ces réglages sont personnels à votre compte, pour ce foyer.</p><label className="field">Liste de courses<Choice label="Liste de courses du tableau de bord" value={p.shoppingId||snapshot.entities.find(e=>e.kind==="shopping")?.id||""} onChange={v=>update("shoppingId",v)} options={snapshot.entities.filter(e=>e.kind==="shopping").map(e=>({value:e.id,label:String(e.data.name)}))}/></label><label className="field">Checklist<Choice label="Checklist du tableau de bord" value={p.checklistId||snapshot.entities.find(e=>e.kind==="checklist")?.id||""} onChange={v=>update("checklistId",v)} options={snapshot.entities.filter(e=>e.kind==="checklist").map(e=>({value:e.id,label:String(e.data.name)}))}/></label><label className="field">Affichage en mode cuisine<Choice label="Disposition" value={p.layout||"side"} onChange={v=>update("layout",v)} options={[{value:"side",label:"Courses et tâches côte à côte"},{value:"rotate",label:"Une liste à la fois, avec rotation"}]}/></label>{p.layout==="rotate"&&<label className="field">Rotation toutes les (secondes)<input type="number" min="5" max="300" value={p.rotation||15} onChange={e=>update("rotation",Number(e.target.value))}/></label>}<label className="field">Caméra par défaut<Choice label="Caméra par défaut" value={p.camera||"environment"} onChange={v=>update("camera",v)} options={[{value:"environment",label:"Arrière — téléphone"},{value:"user",label:"Avant — tablette"}]}/></label><div className="form-row"><label className="field">Couleur heures pleines<input type="color" value={p.peakColor||"#ffffff"} onChange={e=>update("peakColor",e.target.value)}/></label><label className="field">Couleur heures creuses<input type="color" value={p.offPeakColor||"#e7eeff"} onChange={e=>update("offPeakColor",e.target.value)}/></label></div><button className="primary-button" type="submit" disabled={busy}>Enregistrer mes préférences</button></form><div className="flex flex-col gap-5"><AppearanceSettings/><section className="management-card settings-section"><h3>Rappels du foyer</h3><p>Gardez une petite place pour les choses qu’on oublie facilement.</p><button className="secondary-button mt-5" onClick={onNotifications}><Bell size={15}/>Gérer les notifications</button></section>{isAdmin&&<form className="management-card settings-section form-stack" onSubmit={async e=>{e.preventDefault();try{await onRename(name.trim());toast.success("Foyer renommé");}catch{}}}><h3>Notre foyer</h3><label className="field">Nom du foyer<input required value={name} onChange={e=>setName(e.target.value)} maxLength={150}/></label><button className="secondary-button" type="submit" disabled={busy}>Enregistrer le nom</button></form>}<section className="management-card settings-section"><h3>Votre compte</h3><p>{snapshot.user?.name}<br/>{snapshot.user?.email}</p>{!demo&&<button className="secondary-button mt-5" onClick={async()=>{try{const response=await fetch("/api/auth/logout",{method:"POST",headers:{"Content-Type":"application/json"},body:"{}"});if(!response.ok)throw new Error("La déconnexion a échoué. Réessayez.");window.location.assign("/connexion");}catch(error){toast.error(error instanceof Error?error.message:"Déconnexion indisponible.");}}}><LogOut size={15}/>Se déconnecter</button>}<p className="helper mt-5">Sur téléphone ou tablette, ajoutez MyHomeIA à l’écran d’accueil depuis le menu de votre navigateur.</p></section></div></div>;
}

function Notifications({snapshot,demo,onSave}:{snapshot:Snapshot;demo:boolean;onSave:(p:Preferences)=>Promise<void>}) {
 const [enabled,setEnabled]=useState(!!snapshot.preferences.notifications),[message,setMessage]=useState("");
 const activate=async(value:boolean)=>{
  if(demo){setMessage("Connectez-vous à votre foyer pour activer les rappels sur cet appareil.");return;}
  try{
   if(typeof Notification==="undefined"||!("serviceWorker" in navigator))throw new Error("Ce navigateur ne permet pas les notifications. Sur iPhone/iPad, installez l’application sur l’écran d’accueil.");
   const registration=await navigator.serviceWorker.ready;
   if(value){
    const permission=await Notification.requestPermission();if(permission!=="granted")throw new Error("Les notifications sont bloquées. Autorisez-les dans les paramètres du navigateur.");
    if("PushManager" in window){
     const keysResponse=await fetch("/api/push");const keys=await keysResponse.json() as {publicKey?:string;error?:string};if(!keysResponse.ok||!keys.publicKey)throw new Error(keys.error||"Notifications indisponibles.");
     const binary=atob(keys.publicKey.replaceAll("-","+").replaceAll("_","/"));const key=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)key[i]=binary.charCodeAt(i);
     const subscription=await registration.pushManager.getSubscription()||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});
     const response=await fetch("/api/push",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"subscribe",householdId:snapshot.household?.id,subscription:subscription.toJSON()})});const body=await response.json() as {error?:string};if(!response.ok)throw new Error(body.error||"Abonnement indisponible.");
    }
   }else if("PushManager" in window){const subscription=await registration.pushManager.getSubscription();if(subscription)await fetch("/api/push",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"unsubscribe",householdId:snapshot.household?.id,endpoint:subscription.endpoint})});}
   await onSave({notifications:value});setEnabled(value);setMessage(value?("PushManager" in window?"Cet appareil est prêt à recevoir les notifications. Les rappels Push fonctionnent aussi lorsque l’application est fermée, tant que le NAS reste allumé et connecté à Internet.":"Les rappels s’afficheront lorsque l’application reste ouverte. Ce navigateur ne prend pas en charge les notifications Push."):"Les rappels sont désactivés.");
  }catch(e){setMessage(e instanceof Error?e.message:"Activation impossible.");}
 };
 const test=async()=>{try{const registration=await navigator.serviceWorker.ready;const subscription=await registration.pushManager.getSubscription();if(!subscription)throw new Error("Activez d’abord les notifications sur cet appareil.");const response=await fetch("/api/push",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"test",householdId:snapshot.household?.id,endpoint:subscription.endpoint})});const body=await response.json() as {error?:string};if(!response.ok)throw new Error(body.error||"Test impossible.");setMessage("Notification de test envoyée sur cet appareil.");}catch(e){setMessage(e instanceof Error?e.message:"Test impossible.");}};
 return <><DialogTitle className="dialog-title">Les petits rappels</DialogTitle><DialogDescription>Pour penser à sortir le bon bac, le bon soir.</DialogDescription><div className="flex items-center justify-between"><span className="helper">Rappels de sortie des poubelles</span><Switch checked={enabled} onCheckedChange={v=>void activate(v)} aria-label="Activer les rappels"/></div>{message&&<p className="helper" role="status">{message}</p>}{enabled&&!demo&&<button className="secondary-button" onClick={()=>void test()}><Bell size={16}/>Envoyer une notification de test</button>}{upcomingWaste(snapshot.entities).map(e=><div className="notification-item" key={e.id}><strong>{e.data.name}</strong><span>{e.days===0?"Ce soir":`Dans ${e.days} jour(s)`} à {e.data.reminder}</span></div>)}<p className="warning-note">Les rappels s’affichent dans l’application lorsqu’elle est ouverte. Les appareils compatibles avec les notifications Push peuvent aussi les recevoir lorsque l’application est fermée, avec le NAS allumé et connecté à Internet. Sur iPhone/iPad : iOS 16.4 ou supérieur, application ajoutée à l’écran d’accueil.</p></>;
}


